 15	// Pack is a versioned bundle of redaction rules loaded from a single file
 16	// under .entire/redactors/. Both YAML and JSON encodings are accepted; the
 17	// schema is identical.
 18	type Pack struct {
 19		Name        string `json:"name"                  yaml:"name"`
 20		Version     string `json:"version"               yaml:"version"`
 21		Description string `json:"description,omitempty" yaml:"description"`
 22		Rules       []Rule `json:"rules"                 yaml:"rules"`
 23	
 24		// SourcePath is the file the pack was loaded from. Populated by
 25		// ParsePack; used in log lines so users can find the offending file.
 26		SourcePath string `json:"-" yaml:"-"`
 27	}
 28	
 29	// Rule is a single redaction rule within a Pack.
 30	type Rule struct {
 31		ID          string   `json:"id"                    yaml:"id"`
 32		Description string   `json:"description,omitempty" yaml:"description"`
 33		Regex       string   `json:"regex"                 yaml:"regex"`
 34		Samples     []Sample `json:"samples,omitempty"     yaml:"samples"`
 35	}
