 44	// ParsePack decodes a single pack file. sourcePath is used both to pick
 45	// the encoding (YAML by default; JSON only when the extension is .json)
 46	// and to enforce that the pack's `name` matches the filename stem.
 47	func ParsePack(data []byte, sourcePath string) (*Pack, error) {
 48		var pack Pack
 49		switch strings.ToLower(filepath.Ext(sourcePath)) {
 50		case ".json":
 51			if err := json.Unmarshal(data, &pack); err != nil {
 52				return nil, fmt.Errorf("parse %s: %w", sourcePath, err)
 53			}
 54		default:
 55			if err := yaml.Unmarshal(data, &pack); err != nil {
 56				return nil, fmt.Errorf("parse %s: %w", sourcePath, err)
 57			}
 58		}
 59		pack.SourcePath = sourcePath
 60		if err := validatePack(&pack); err != nil {
 61			return nil, err
 62		}
 63		return &pack, nil
 64	}
 65	
 66	// validatePack enforces required fields and schema invariants. Regex
 67	// compilation is NOT performed here — that happens during ConfigureCustomRules
 68	// so failures emit the same warn-and-skip path as inline rules.
 69	func validatePack(p *Pack) error {
 70		if p.Name == "" {
 71			return fmt.Errorf("%s: missing required field 'name'", p.SourcePath)
 72		}
 73		if p.Version == "" {
 74			return fmt.Errorf("%s: missing required field 'version'", p.SourcePath)
 75		}
 76		if len(p.Rules) == 0 {
 77			return fmt.Errorf("%s: 'rules' must contain at least one entry", p.SourcePath)
 78		}
 79	
 80		// Name must match filename stem so log lines and discovery stay consistent.
 81		stem := strings.TrimSuffix(filepath.Base(p.SourcePath), filepath.Ext(p.SourcePath))
 82		if stem != p.Name {
 83			return fmt.Errorf("%s: pack name %q does not match filename stem %q", p.SourcePath, p.Name, stem)
 84		}
 85	
 86		seen := make(map[string]struct{}, len(p.Rules))
 87		for i, r := range p.Rules {
 88			if r.ID == "" {
 89				return fmt.Errorf("%s: rules[%d] missing required field 'id'", p.SourcePath, i)
 90			}
 91			if r.Regex == "" {
 92				return fmt.Errorf("%s: rules[%d] (%s) missing required field 'regex'", p.SourcePath, i, r.ID)
 93			}
 94			if _, dup := seen[r.ID]; dup {
 95				return fmt.Errorf("%s: duplicate rule id %q", p.SourcePath, r.ID)
 96			}
 97			seen[r.ID] = struct{}{}
 98		}
 99		return nil
100	}
