102	// LoadPacks discovers and parses all rule packs in dir, including any
103	// subdirectories (so the conventional .entire/redactors/local/ path for
104	// personal/uncommitted rules is picked up automatically). Files with the
105	// extensions .yaml, .yml, and .json are considered packs; other files are
106	// ignored. A missing directory is treated as "no packs configured" and
107	// returns no error. Per-file parse errors are slog.Warn'd and the file is
108	// skipped — never fatal — so one bad file does not silence the rest.
109	func LoadPacks(dir string) ([]*Pack, error) {
110		info, err := os.Stat(dir)
111		if err != nil {
112			if os.IsNotExist(err) {
113				return nil, nil
114			}
115			return nil, fmt.Errorf("stat redactors dir %s: %w", dir, err)
116		}
117		if !info.IsDir() {
118			return nil, fmt.Errorf("redactors path %s is not a directory", dir)
119		}
120	
121		var packs []*Pack
122		walkErr := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
123			if err != nil {
124				slog.Warn("skipping unreadable redactor pack path",
125					slog.String("path", path),
126					slog.String("error", err.Error()))
127				return nil
128			}
129			if d.IsDir() {
130				return nil
131			}
132			switch strings.ToLower(filepath.Ext(d.Name())) {
133			case ".yaml", ".yml", ".json":
134			default:
135				return nil
136			}
137	
138			data, err := os.ReadFile(path) //nolint:gosec // path comes from WalkDir under a configured dir
139			if err != nil {
140				slog.Warn("skipping unreadable redactor pack",
141					slog.String("path", path),
142					slog.String("error", err.Error()))
143				return nil
144			}
145			pack, err := ParsePack(data, path)
146			if err != nil {
147				slog.Warn("skipping invalid redactor pack",
148					slog.String("path", path),
149					slog.String("error", err.Error()))
150				return nil
151			}
152			packs = append(packs, pack)
153			return nil
154		})
155		if walkErr != nil {
156			return nil, fmt.Errorf("walk redactors dir %s: %w", dir, walkErr)
157		}
158		return packs, nil
159	}

