137	// String replaces secrets and PII in s using layered detection:
138	// 1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
139	// 2. Pattern-based: betterleaks regex rules (260+ known secret formats)
140	// 3. Credentialed URIs: URLs containing userinfo passwords
141	// 4. Database connection strings: JDBC, keyword DSNs, and semicolon strings
142	// 4b. User-defined custom rules: configured via ConfigureCustomRules
143	// 5. Bounded credential key/value pairs: DB_PASSWORD=...
144	// 6. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
145	// A string is redacted if ANY method flags it.
146	func String(s string) string {
147		var regions []taggedRegion
148	
149		// 1. Entropy-based detection (secrets — always on).
150		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
151			start, end := loc[0], loc[1]
152	
153			// Don't consume characters that are part of JSON/string escape sequences.
154			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
155			// (consuming the 'n' from '\n'), and after replacement the '\' would be
156			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
157			// Only skip for known JSON escape letters to avoid trimming real secrets
158			// that happen to follow a literal backslash in decoded content.
159			if start > 0 && s[start-1] == '\\' {
160				switch s[start] {
161				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
162					start++
163					if end-start < 10 {
164						continue
165					}
166				}
167			}
168	
169			if shannonEntropy(s[start:end]) > entropyThreshold {
170				regions = append(regions, taggedRegion{region: region{start, end}})
171			}
172		}
173	
174		// 2. Pattern-based detection via betterleaks (secrets — always on).
175		if d := getDetector(); d != nil {
176			for _, f := range d.DetectString(s) {
177				if f.Secret == "" {
178					continue
179				}
180				searchFrom := 0
181				for {
182					idx := strings.Index(s[searchFrom:], f.Secret)
183					if idx < 0 {
184						break
185					}
186					absIdx := searchFrom + idx
187					regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
188					searchFrom = absIdx + len(f.Secret)
189				}
190			}
191		}
192	
193		// 3. Credentialed URIs (secrets — always on).
194		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
195			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
196		}
197	
198		// 4. Database and connection-string detection (secrets — always on).
199		regions = append(regions, detectConnectionStrings(s)...)
200	
201		// 4b. User-defined custom rules (secrets — only runs when configured).
202		regions = append(regions, detectCustomRules(getCustomRulesConfig(), s)...)
203	
204		// 5. Bounded credential key/value detection (secrets — always on).
205		regions = append(regions, detectCredentialValues(s)...)
206	
207		// 6. PII detection (opt-in — only runs when configured).
208		regions = append(regions, detectPII(getPIIConfig(), s)...)
209	
210		if len(regions) == 0 {
211			return s
212		}
213	
214		// Merge overlapping regions and build result.
215		sort.Slice(regions, func(i, j int) bool {
216			if regions[i].start != regions[j].start {
217				return regions[i].start < regions[j].start
218			}
219			if regions[i].end != regions[j].end {
220				return regions[i].end > regions[j].end // larger region first
221			}
222			return regions[i].label < regions[j].label // deterministic tie-break
223		})
224		merged := []taggedRegion{regions[0]}
225		for _, r := range regions[1:] {
226			last := &merged[len(merged)-1]
227			if r.start <= last.end {
228				if r.end > last.end {
229					last.end = r.end
230				}

