 48	// ParsePack decodes a single pack file. sourcePath is used both to pick
 49	// the encoding (YAML by default; JSON only when the extension is .json)
 50	// and to enforce that the pack's `name` matches the filename stem.
 51	func ParsePack(data []byte, sourcePath string) (*Pack, error) {
 52		var pack Pack
 53		switch strings.ToLower(filepath.Ext(sourcePath)) {
 54		case ".json":
 55			decoder := json.NewDecoder(bytes.NewReader(data))
 56			decoder.DisallowUnknownFields()
 57			if err := decoder.Decode(&pack); err != nil {
 58				return nil, fmt.Errorf("parse %s: %w", sourcePath, err)
 59			}
 60		default:
 61			decoder := yaml.NewDecoder(bytes.NewReader(data))
 62			decoder.KnownFields(true)
 63			if err := decoder.Decode(&pack); err != nil {
 64				return nil, fmt.Errorf("parse %s: %w", sourcePath, err)
 65			}
 66		}
 67		pack.sourcePath = sourcePath
 68		if err := validatePack(&pack); err != nil {
 69			return nil, err
 70		}
 71		return &pack, nil
 72	}
