 74	// validatePack enforces required fields and schema invariants. Regex
 75	// compilation is NOT performed here — that happens during ConfigureCustomRules
 76	// so failures emit the same warn-and-skip path as inline rules.
 77	func validatePack(p *Pack) error {
 78		if p.Name == "" {
 79			return fmt.Errorf("%s: missing required field 'name'", p.sourcePath)
 80		}
 81		if p.Version == "" {
 82			return fmt.Errorf("%s: missing required field 'version'", p.sourcePath)
 83		}
