137	// String replaces secrets and PII in s using layered detection:
138	// 1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
139	// 2. Pattern-based: betterleaks regex rules (260+ known secret formats)
140	// 3. Credentialed URIs: URLs containing userinfo passwords
141	// 4. Database connection strings: JDBC, keyword DSNs, and semicolon strings
142	// 5. User-defined custom rules: configured via ConfigureCustomRules
143	// 6. Bounded credential key/value pairs: DB_PASSWORD=...
144	// 7. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
145	// A string is redacted if ANY method flags it.
146	func String(s string) string {
147		var regions []taggedRegion
148	
149		// 1. Entropy-based detection (secrets — always on).
150		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
151			start, end := loc[0], loc[1]
152	
153			// Don't consume characters that are part of JSON/string escape sequences.
154			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
155			// (consuming the 'n' from '\n'), and after replacement the '\' would be
156			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
157			// Only skip for known JSON escape letters to avoid trimming real secrets
158			// that happen to follow a literal backslash in decoded content.
159			if start > 0 && s[start-1] == '\\' {
160				switch s[start] {
161				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
162					start++
163					if end-start < 10 {
164						continue
165					}
166				}
167			}
