 10	func TestParsePack_YAMLValid(t *testing.T) {
 11		t.Parallel()
 12	
 13		body := []byte(`
 14	name: acme-internal
 15	version: 1.0.0
 16	description: Internal ACME tokens
 17	rules:
 18	  - id: acme-token
 19	    regex: 'ACME_TOKEN_[A-Za-z0-9]{20,}'
 20	    samples:
 21	      - { input: "REDACTED", redacted: true }
 22	      - { input: "ACME_TOKEN_short", redacted: false }
 23	  - id: acme-session
 24	    regex: 'asess_[a-f0-9]{32}'
 25	`)
 26	
 27		pack, err := ParsePack(body, "acme-internal.yaml")
 28		if err != nil {
 29			t.Fatalf("ParsePack: %v", err)
 30		}
 31		if pack.Name != "acme-internal" {
 32			t.Errorf("Name: want acme-internal, have %q", pack.Name)
 33		}
 34		if pack.Version != "1.0.0" {
 35			t.Errorf("Version: want 1.0.0, have %q", pack.Version)
 36		}
 37		if len(pack.Rules) != 2 {
 38			t.Fatalf("Rules: want 2, have %d", len(pack.Rules))
 39		}
 40		if pack.Rules[0].ID != "acme-token" {
 41			t.Errorf("Rules[0].ID: want acme-token, have %q", pack.Rules[0].ID)
 42		}
 43		if len(pack.Rules[0].Samples) != 2 {
 44			t.Errorf("Rules[0].Samples: want 2, have %d", len(pack.Rules[0].Samples))
 45		}
 46		if !pack.Rules[0].Samples[0].Redacted {
 47			t.Error("Rules[0].Samples[0].Redacted: want true")
 48		}
 49	}
