 11	// resetCustomRulesForTest clears the package-level config so tests don't leak
 12	// state into each other. Tests cannot run in parallel against the global, so
 13	// the helper is invoked at top-of-test in a t.Cleanup pattern.
 14	func resetCustomRulesForTest(t *testing.T) {
 15		t.Helper()
 16		customConfigMu.Lock()
 17		customConfig = nil
 18		customConfigMu.Unlock()
 19		t.Cleanup(func() {
 20			customConfigMu.Lock()
 21			customConfig = nil
 22			customConfigMu.Unlock()
 23		})
 24	}
