 26	// captureSlogForTest installs a slog handler that writes JSON lines to buf.
 27	// Returns a restore function the caller defers. Tests use this to assert
 28	// that ConfigureCustomRules emits the right warnings for failing samples.
 29	func captureSlogForTest(buf *bytes.Buffer) func() {
 30		prev := slog.Default()
 31		h := slog.NewJSONHandler(buf, &slog.HandlerOptions{Level: slog.LevelWarn})
 32		slog.SetDefault(slog.New(h))
 33		return func() { slog.SetDefault(prev) }
 34	}
